// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 dummy) public {
        vm.assume(dummy < type(uint256).max); 
        bytes memory result = bytes(c.version());
        assertTrue(result.length >= 1);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) external {
        require(caller != c.DEPOSITOR_ACCOUNT(), "precondition: caller is not depositor");
        bool reverted = false;
        assembly {
            let success := call(gas(), sload(c.slot), 0, 0, 0, 0, 0)
            reverted := iszero(success)
        }
        assert(false);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(true);
        bool reverted; try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(reverted || caller == c.depositorAccount());
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address caller, uint64 _number) public returns (bool success) {
        vm.prank(caller);
        try c.setL1BlockValues(_number, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            success = true;
        } catch {
            success = false;
        }
        bool isDepositor = caller == c.DEPOSITOR_ACCOUNT();
        assert(success == isDepositor);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != c.depositorAccount());
        bool reverted;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, address depositor) public {
        bool succeeded;
        address originalDepositor = c.depositorAccount();

        require(caller != depositor, "caller must differ from depositor param");

        // Set depositorAccount to the provided depositor address so we control access
        // depositorAccount is public and has no setter; we must use an existing mechanism.
        // Actually, depositorAccount is a public state variable with no setter in C.
        // The only way to change it is via the constructor, which we cannot call.
        // Therefore, we must work with the existing depositorAccount.
        // The rule must hold for the actual depositorAccount in c.
        // We read the current depositorAccount and check behavior against it.
        // The rule: a call from depositorAccount succeeds; a call from anyone else reverts.

        // Call as the depositor account using a low-level call to simulate msg.sender
        // Since we cannot change msg.sender of our own calls, we use the caller parameter
        // and arrange that the call is made by the appropriate address.
        // But we cannot change msg.sender in Solidity without low-level calls.
        // The test function must be called by the address we want to test.
        // Instead, we check the invariant by observing the state after calls made by different accounts.
        // The simplest way: the assert checks that the function reverts iff msg.sender != depositorAccount.
        // We simulate this by checking the revert behavior when called from this contract
        // and the depositor account status.
        // Since we cannot guarantee who calls the test function, we express the rule as:
        // for any transaction to setL1BlockValues, it reverts unless msg.sender == depositorAccount.
        // But we cannot make external calls as different senders from within one function.
        // We need to capture the revert condition directly.
        // The rule: calling setL1BlockValues from any address other than depositorAccount MUST revert.
        // We know depositorAccount is constant DEPOSITOR_ACCOUNT = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001.
        // We test by calling it from this contract (which is not the depositor) and checking revert.

        // Make the call from this test contract, which is not the depositor
        bool reverted = false;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            succeeded = true;
        } catch {
            reverted = true;
        }

        // The rule: if this contract is not the depositor, the call must revert.
        // For M, the call would succeed because M requires msg.sender != depositorAccount.
        assert(reverted == (address(this) != c.depositorAccount()));
    }
}
